client_script:
frappe.web_form.after_load = function() {
  var doc = frappe.web_form.doc;
  var roles = (frappe.boot && frappe.boot.user && frappe.boot.user.roles) ? frappe.boot.user.roles : [];
  var state = (doc && (doc.workflow_state || doc.statut)) || 'Brouillon';
  var total = (doc && (doc.total_ttc || doc.sous_total)) || 0;
  if (doc && doc.name) {
    var refEl = document.createElement('div');
    refEl.innerHTML = '<div style="margin-bottom:12px;padding:8px 16px;background:#e3f2fd;color:#1565c0;border-left:4px solid #1976d2;border-radius:6px;display:inline-block;font-weight:700;font-size:14px;">Réf. : ' + (doc.numero_bc || doc.name) + '</div>';
    var w = document.querySelector('.web-form-wrapper') || document.querySelector('.container');
    if (w) w.prepend(refEl);
  }
  // Signature de l'autorisateur : éditable UNIQUEMENT à 'En attente Autorisation'
  // par DGA (montant <= 100000) ou DG (tout montant) ou System Manager.
  try { frappe.web_form.set_df_property('signature_dg','read_only',1); } catch(e){}
  var isDGA = roles.indexOf('DGA')!==-1, isDG = roles.indexOf('Directeur Général')!==-1, isSM = roles.indexOf('System Manager')!==-1;
  if (state === 'En attente Autorisation' && (isSM || isDG || (isDGA && total <= 100000))) {
    try { frappe.web_form.set_df_property('signature_dg','read_only',0); } catch(e){}
  }
  if (doc && (doc.workflow_state || doc.statut)) {
    var st = doc.workflow_state || doc.statut;
    var cm = {'Émis':'#2e7d32','Annulé':'#c62828','Brouillon':'#757575','En attente Visa Audit':'#e65100','En attente Autorisation':'#1565c0'};
    var c = cm[st] || '#1565c0';
    var el = document.createElement('div');
    el.innerHTML = '<div style="margin-bottom:12px;padding:8px 16px;background:'+c+';color:#fff;border-radius:6px;display:inline-block;font-weight:700;">État : '+st+'</div>';
    var w2 = document.querySelector('.web-form-wrapper') || document.querySelector('.container');
    if (w2) w2.prepend(el);
  }
};
